{"jobs": [{"absolute_url": "https://careers.datadoghq.com/detail/8053714/?gh_jid=8053714", "data_compliance": [{"type": "gdpr", "requires_consent": false, "requires_processing_consent": false, "requires_retention_consent": false, "retention_period": null, "demographic_data_consent_applies": false}], "internal_job_id": 3490541, "location": {"name": "Denver, Colorado, USA"}, "metadata": [{"id": 33310, "name": "Time Type", "value": "Full time", "value_type": "single_select"}, {"id": 166208, "name": "Area - Engineering", "value": null, "value_type": "single_select"}, {"id": 498252, "name": "Cost Center", "value": "Technical Solutions - Commercial & Mid-Market Sales Engineering", "value_type": "single_select"}, {"id": 516515, "name": "Geography", "value": "North America", "value_type": "single_select"}, {"id": 9593635, "name": "Early Career Time Type", "value": null, "value_type": "single_select"}, {"id": 29446322, "name": "Pay Transparency Range", "value": {"unit": "USD", "max_value": "122000.0", "min_value": "92000.0"}, "value_type": "currency_range"}, {"id": 31273219, "name": "Does this role require access to ITAR-controlled data?", "value": "I’m not sure", "value_type": "single_select"}, {"id": 58619948, "name": "IC or MG", "value": "IC", "value_type": "single_select"}], "id": 8053714, "updated_at": "2026-09-02T10:22:15-04:00", "requisition_id": "R19916", "title": "Commercial Sales Engineer 2 (AMER - West)", "company_name": "Datadog", "first_published": "2026-07-16T11:57:21-04:00", "language": "en", "application_deadline": null, "content": "&lt;p&gt;Datadog Sales Engineers help qualify and close opportunities with customers and partners by providing technical expertise through sales presentations, product demonstrations, and supporting technical evaluations (POCs). As a Commercial Sales Engineer 2, you will independently own technical engagements throughout the sales cycle, partnering closely with Account Executives to align customer business objectives with Datadog&#39;s platform.&amp;nbsp; You will also collaborate across Engineering, Support, Product, and Customer Success to resolve customer concerns, advocate for customer needs, and serve as a trusted technical advisor throughout the evaluation process.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;If you want to join a friendly, passionate team with limitless potential, we&#39;d love to meet you!&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;At Datadog, we place value in our office culture—the relationships and collaboration it builds and the creativity it brings to the table. We operate as a hybrid workplace to ensure our Datadogs can create a work-life harmony that best fits them.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What You&#39;ll Do:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Partner with the sales team to articulate Datadog&#39;s value proposition, vision, and technical strategy throughout the sales cycle.&lt;/li&gt;
&lt;li&gt;Deliver tailored product demonstrations and technical presentations that map customer challenges to Datadog solutions.&lt;/li&gt;
&lt;li&gt;Assist with technical discovery by identifying customer business objectives, technical challenges, and success criteria.&lt;/li&gt;
&lt;li&gt;Own technical evaluations (POCs) from kickoff through successful completion, proactively driving customer engagement and removing technical blockers.&lt;/li&gt;
&lt;li&gt;Continually expand your expertise across Datadog&#39;s platform while building competitive knowledge and technical credibility.&lt;/li&gt;
&lt;li&gt;Develop trusted relationships with customer technical stakeholders while effectively communicating business value to broader buying teams.&lt;/li&gt;
&lt;li&gt;Contribute to team success by sharing best practices, mentoring newer Sales Engineers, and supporting enablement initiatives.&lt;/li&gt;
&lt;li&gt;Think creatively to solve a wide variety of technical challenges throughout the pre-sales lifecycle.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Who You Are:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Ideally 1.5 years or greater as a Sales Engineer or in a comparable customer-facing technical role.&lt;/li&gt;
&lt;li&gt;Strong understanding of cloud infrastructure, modern application architectures, observability, and/or DevOps technologies.&lt;/li&gt;
&lt;li&gt;Comfortable independently leading technical presentations, product demonstrations, and evaluations.&lt;/li&gt;
&lt;li&gt;Able to translate technical capabilities into meaningful business outcomes for customers.&lt;/li&gt;
&lt;li&gt;Effective communicating with both technical practitioners (Developers, SREs, Platform Engineers, Operations teams) and business stakeholders.&lt;/li&gt;
&lt;li&gt;Comfortable navigating multiple customer stakeholders while managing several active evaluations simultaneously.&lt;/li&gt;
&lt;li&gt;Curious, adaptable, and eager to continually learn and expand technical expertise.&lt;/li&gt;
&lt;li&gt;Experience with modern infrastructure technologies, such as cloud platforms, containers, Kubernetes, microservices, networking, and/or operating systems.&lt;/li&gt;
&lt;li&gt;Able to sit for up to 4 hours while traveling to and from client sites.&lt;/li&gt;
&lt;li&gt;Able to travel via auto, train, or air up to 25% of the time.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Datadog values people from all walks of life. We understand not everyone will meet every qualification on day one—and that&#39;s okay. If you&#39;re passionate about technology and excited to grow your skills, we encourage you to apply.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Benefits and Growth&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Best-in-class onboarding&lt;/li&gt;
&lt;li&gt;Generous global benefits&lt;/li&gt;
&lt;li&gt;Intra-departmental mentor and buddy program&lt;/li&gt;
&lt;li&gt;New hire stock equity (RSUs) and Employee Stock Purchase Plan (ESPP)&lt;/li&gt;
&lt;li&gt;Continuous professional development, product training, and career growth opportunities&lt;/li&gt;
&lt;li&gt;An inclusive company culture with Community Guilds and Inclusion Talks&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Benefits and Growth listed above may vary based on the country of your employment and the nature of your employment with Datadog.&lt;/em&gt;&lt;/p&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;Datadog offers a competitive salary and equity package, and may include variable compensation. Actual compensation is based on factors such as the candidate&#39;s skills, qualifications, and experience. In addition, Datadog offers a wide range of best in class, comprehensive and inclusive employee benefits for this role including healthcare, dental, parental planning, and mental health benefits, a 401(k) plan and match, paid time off, fitness reimbursements, and a discounted employee stock purchase plan.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;The reasonably estimated yearly salary for this role at Datadog is:&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$92,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$122,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;hr&gt;
&lt;p&gt;&lt;strong&gt;About Datadog:&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Datadog is the leading observability and security platform for the AI era, providing businesses with unified visibility across the technology stack to manage complexity at scale. It brings applications, infrastructure, data, models, and security into one place, using AI to detect and resolve issues before they impact customers. Trusted globally by Fortune 500 companies and high-growth AI leaders, Datadog enables businesses to move faster with clarity and confidence. Learn more about #DatadogLife on &lt;a href=&quot;https://www.instagram.com/datadoghq/?hl=en&quot; target=&quot;_blank&quot;&gt;Instagram&lt;/a&gt;, &lt;a href=&quot;https://www.linkedin.com/company/datadog&quot; target=&quot;_blank&quot;&gt;LinkedIn,&lt;/a&gt; and &lt;a href=&quot;https://learn.datadoghq.com/&quot; target=&quot;_blank&quot;&gt;Datadog Learning Center. &lt;/a&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;p data-renderer-start-pos=&quot;215&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Equal Opportunity at Datadog:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Datadog is proud to offer &lt;a href=&quot;https://www.eeoc.gov/sites/default/files/2023-06/22-088_EEOC_KnowYourRights6.12ScreenRdr.pdf&quot; target=&quot;_blank&quot;&gt;equal employment opportunity&lt;/a&gt; to everyone regardless of race, color, ancestry, religion, sex, national origin, sexual orientation, age, citizenship, marital status, disability, gender identity, veteran status, and other characteristics protected by law. We also consider qualified applicants regardless of criminal histories, consistent with legal requirements. Here are our &lt;a href=&quot;https://www.datadoghq.com/legal/candidate-legal-notices/&quot; target=&quot;_blank&quot;&gt;Candidate Legal Notices&lt;/a&gt; for your reference.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Datadog endeavors to make our Careers Page accessible to all users. If you would like to contact us regarding the accessibility of our website or need assistance completing the application process, please complete &lt;a href=&quot;https://docs.google.com/forms/d/e/1FAIpQLSeoJeduEZ2NdZF_65uZmWUrCM-zee7yADXX1s6Xr9zAGq8iKA/viewform&quot; target=&quot;_blank&quot;&gt;this form&lt;/a&gt;. This form is for accommodation requests only and cannot be used to inquire about the status of applications.&amp;nbsp;&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;662&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Privacy and AI Guidelines:&lt;/strong&gt;&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;662&quot;&gt;Any information you submit to Datadog as part of your application will be processed in accordance with Datadog’s&amp;nbsp;&lt;a class=&quot;c-link&quot; href=&quot;https://www.datadoghq.com/legal/applicant-candidate-privacy/&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://www.datadoghq.com/legal/applicant-candidate-privacy/&quot; data-sk=&quot;tooltip_parent&quot;&gt;Applicant and Candidate Privacy Notice&lt;/a&gt;. For information on our AI policy, please visit &lt;a href=&quot;https://www.datadoghq.com/legal/interviewing-at-datadog-ai-guidelines/&quot; target=&quot;_blank&quot;&gt;Interviewing at Datadog AI Guidelines&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;", "departments": [{"id": 202108, "name": "Commercial & Mid-Market Sales Engineering", "child_ids": [], "parent_id": 9023}], "offices": [{"id": 61865, "name": "Denver", "location": "Denver, Colorado, United States", "child_ids": [], "parent_id": 78231}], "ai_disclaimer": null, "include_ai_disclaimer": null, "ai_opt_out_request_url": null}]}
